package com.lmspilot.organization.api;import com.lmspilot.contracts.Permissions;import com.lmspilot.support.api.ApiException;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/organization/memberships") public class OrganizationMembershipController{private final OrganizationMembershipService service;public OrganizationMembershipController(OrganizationMembershipService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('"+Permissions.ORGANIZATION_READ+"')") public List<MembershipResponse> list(@RequestParam(required=false)UUID userId,@RequestParam(required=false)UUID unitId){if(userId!=null)return service.byUserForRequester(userId);if(unitId!=null)return service.byUnit(unitId);throw new ApiException(HttpStatus.BAD_REQUEST,"FILTER_REQUIRED","Cần userId hoặc unitId");}@PostMapping("/bulk") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyAuthority('"+Permissions.ORGANIZATION_MEMBERSHIP_MANAGE+"','"+Permissions.ORGANIZATION_MANAGE+"')") public List<MembershipResponse> grant(@Valid @RequestBody BulkMembershipRequest in){return service.grant(in);}@DeleteMapping("/bulk") @PreAuthorize("hasAnyAuthority('"+Permissions.ORGANIZATION_MEMBERSHIP_MANAGE+"','"+Permissions.ORGANIZATION_MANAGE+"')") public Map<String,Long> revoke(@Valid @RequestBody RevokeMembershipRequest in){return service.revoke(in);}}
